let p=TB.fresh(),tab='capture',db,selected=null,search='',filter='all',sort='name',worker=null,progress=null,training=false,saveTimer,saveTick=0,noticeTimer,latest=[],validCount=0,badRows=0,recording=null,recordTimer=null,serialMessage='Disconnected',replayId=null,replayOffset=0;
