function notify(message,error=false){$('#notice').textContent=message;$('#notice').className=error?'error':'';$('#notice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').hidden=true,error?20000:8000);}
function safe(fn){return async(...args)=>{try{await fn(...args);}catch(e){notify(e.message||String(e),true);}};}
function bind(id,event,fn){const el=$('#'+id);if(el)el.addEventListener(event,safe(fn));}
function download(data,name,type='application/json'){const blob=data instanceof Blob?data:new Blob([data],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
const fileBase=()=>p.name.replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-|-$/g,'').slice(0,65)||'tinybench-project';
function activeRun(){return p.runs.find(r=>r.id===p.activeRun)||null;}
function stale(run){return run&&run.signature!==TB.signature(p);}
function requestSave(){if(saveBlocked){$('#saveState').textContent='! Save blocked · export JSON';return;}clearTimeout(saveTimer);const tick=++saveTick;$('#saveState').textContent='○ Unsaved';$('#saveState').className='save-state';saveTimer=setTimeout(()=>save(tick),250);updateTop();}
async function save(tick=saveTick){if(saveBlocked)return;if(!db){$('#saveState').textContent='! Save unavailable';return;}$('#saveState').textContent='◌ Saving…';try{let nextRevision;await new Promise((res,rej)=>{const tx=db.transaction('projects','readwrite'),store=tx.objectStore('projects'),get=store.get('revision');let conflict=false;get.onsuccess=()=>{const current=get.result||0;if(current!==expectedRevision){conflict=true;tx.abort();return;}nextRevision=current+1;store.put(TB.clone(p),'current');store.put(nextRevision,'revision');};tx.oncomplete=res;tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(conflict?new Error('Another tab saved this project. Save JSON from this tab before reloading to avoid overwriting its changes.'):tx.error||new Error('Save aborted'));});expectedRevision=nextRevision;if(tick===saveTick){$('#saveState').textContent='● Saved locally';$('#saveState').className='save-state';}}catch(err){saveBlocked=true;$('#saveState').textContent='! Save blocked · export JSON';$('#saveState').className='save-state error';notify('Autosave stopped. Save JSON now. '+err.message,true);}}
function validateLoaded(project){TB.validateProject(project);if(!Array.isArray(project.runs)||project.runs.length>8)throw new Error('Project has an invalid run history (maximum 8).');project.runs.forEach(TB.validateRun);if(!Number.isFinite(project.threshold)||project.threshold<.1||project.threshold>1)throw new Error('Invalid prediction threshold.');for(const key of ['assumptions','evidence'])if(typeof project[key]!=='string'||project[key].length>6000)throw new Error('Invalid project notes.');project.records.forEach(r=>{if(r.capture)TBAcquisition.validateCapture(r.capture,r.rows);});if(project.recovery)TBAcquisition.validateDraft(project.recovery,project);if(project.revisions){if(!Array.isArray(project.revisions)||project.revisions.length>3)throw new Error('Invalid dataset revision history.');for(const r of project.revisions){if(typeof r.name!=='string'||r.name.length>80)throw new Error('Invalid revision name.');TB.validateProject({...project,...r.snapshot,revisions:[]});}}if(project.audioDraft){const d=project.audioDraft;if(project.config.features!=='audio'||!Array.isArray(d.samples)||d.samples.length<512||d.samples.length>320000||!d.samples.every(v=>Number.isFinite(v)&&Math.abs(v)<=1)||typeof d.origin!=='string'||typeof d.name!=='string')throw new Error('Invalid audio clip draft.');}if(project.trainingJob){if(!['running','interrupted'].includes(project.trainingJob.status)||typeof project.trainingJob.dataSignature!=='string')throw new Error('Invalid training recovery.');TB.validateConfig(project.trainingJob.config);}project.version=TB.VERSION;return project;}
async function init(){
  document.documentElement.dataset.theme=localStorage.getItem('tinybench-theme')||'light';$('#theme').value=document.documentElement.dataset.theme;
  try{db=await new Promise((resolve,reject)=>{const req=indexedDB.open('tinybench',1);req.onupgradeneeded=()=>req.result.createObjectStore('projects');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});const stored=await new Promise((res,rej)=>{const tx=db.transaction('projects'),store=tx.objectStore('projects'),current=store.get('current'),revision=store.get('revision');tx.oncomplete=()=>res({project:current.result,revision:revision.result||0});tx.onerror=()=>rej(tx.error);});const saved=stored.project;expectedRevision=stored.revision;if(saved)p=validateLoaded(saved);if(p.trainingJob)p.trainingJob.status='interrupted';$('#saveState').textContent='● Saved locally';}
  catch(e){saveBlocked=true;restoreFailed=true;$('#saveState').textContent='! Recovery needed';$('#saveState').className='save-state error';notify('Could not restore local data. Your stored copy has not been overwritten. Open a JSON backup, or start a new project. '+e.message,true);}
  updateTop();render();
  if('serviceWorker' in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('./sw.js').then(async()=>{await navigator.serviceWorker.ready;$('#offlineState').textContent='Offline cache ready · Keep JSON backups of your data.';}).catch(()=>$('#offlineState').textContent='Offline cache unavailable · Serve on HTTPS or localhost.');}
  else $('#offlineState').textContent='USB & offline caching need HTTPS or localhost · CSV and training available over HTTP.';
}
function updateTop(){$('#projectName').textContent=p.name;$('#recordCount').textContent=p.records.length;$$('#workflow button').forEach(b=>{if(b.dataset.tab===tab)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});}
