function pageHead(step,title,sub,buttons=''){return`<div class="page-head"><div><span class="eyebrow">${step}</span><h1>${title}</h1><p>${sub}</p></div>${buttons?'<div class="actions">'+buttons+'</div>':''}</div>`;}
function empty(title,text,buttons){return`<div class="big-empty"><span class="empty-icon" aria-hidden="true">⌁</span><h2>${title}</h2><p>${text}</p><div class="actions">${buttons}</div></div>`;}
function render(){
  const root=$('#workspace');if(tab==='capture')root.innerHTML=captureView();if(tab==='dataset')root.innerHTML=datasetView();if(tab==='train')root.innerHTML=trainView();if(tab==='test')root.innerHTML=testView();if(tab==='export')root.innerHTML=exportView();if(tab==='train'&&p.trainingJob&&!training)root.insertAdjacentHTML('afterbegin',trainingRecoveryView());if(['train','export'].includes(tab))root.insertAdjacentHTML('beforeend',localWorkerView());bindView();bindLocal();requestAnimationFrame(paint);
}
function badge(split){return`<span class="badge ${split==='test'?'warn':split==='validation'?'neutral':''}">${esc(split)}</span>`;}
function partitions(){return TB.task(p)==='anomaly'?['train','calibration','validation','test']:['train','validation','test'];}
function splitStats(){return partitions().map(key=>{const rs=p.records.filter(r=>r.split===key),groups=new Set(rs.map(r=>r.group));return`<div class="stat"><strong>${rs.length}</strong><small>${key==='train'?'Training':key==='test'?'Held-out test':key==='calibration'?'Calibration':'Validation'} · ${groups.size} sessions</small></div>`;}).join('');}
function captureView(){if(p.config.features==='audio')return audioCaptureView();return pageHead('01 / OBSERVE THE WORLD','Teach it what to notice.','Collect a few honest examples of each state. Keep each recording short, clearly labeled, and representative.',`<button id="demoBtn">Try the demonstration</button><button id="csvBtn">Import CSV</button>`)+`
 <div class="grid"><div class="stack"><section class="panel"><div class="panel-head"><div><span class="eyebrow">LIVE SENSOR INPUT</span><h2>Your board, on the bench</h2></div><span class="badge" id="connectionBadge">${esc(serial.state)}</span></div><div class="scope"><canvas id="signalCanvas" aria-label="Live sensor waveform" role="img"></canvas><div class="empty-scope" id="signalEmpty" ${latest.length?'hidden':''}>Connect a board streaming sensor CSV,<br>or import a recording to get started.</div></div><div class="scope-caption"><span id="signalStats">${validCount} valid rows · ${badRows} rejected</span><span>${p.sampleRate} Hz configured · ${p.axes.length} channels</span></div><div class="scope-caption"><div class="legend">${p.axes.map((a,i)=>`<span style="--swatch:var(--chart${i%3+1})">${esc(a.name)} [${esc(a.unit)}]</span>`).join('')}</div><span id="serialStatus">${esc(serialMessage)}</span></div><div class="actions"><button id="connectBtn" class="${serial.running?'':'primary'}" ${(!navigator.serial||!isSecureContext)?'disabled':''}>${serial.running?'Disconnect USB':'Connect Arduino'}</button><button id="reconnectBtn" ${serial.running||serial.busy||!serial.selectedPort?'disabled':''}>Retry selected port</button><button id="settingsBtn">Configure channels</button></div><p class="hint">${!navigator.serial||!isSecureContext?'USB capture needs desktop Chrome or Edge on HTTPS or localhost. CSV import is available.':'115200 baud · Close Arduino Serial Monitor before connecting. No firmware changes are made here.'}</p></section>
 ${acquisitionPanel()}<section class="panel"><div class="panel-head"><h2>A useful first experiment</h2><span class="eyebrow">MOTION / 3 CLASSES</span></div><p>Teach an accelerometer to distinguish <strong>still</strong>, <strong>tilted</strong>, and <strong>shaking</strong>. The demonstration contains synthetic examples of all three, ready to train.</p><div class="stat-row">${splitStats()}</div><div class="actions"><button id="datasetBtn">Review dataset →</button></div></section></div>
 <aside class="stack">${recoveryPanel()}<section class="panel olive"><span class="eyebrow">RECORD AN EXAMPLE</span><h2 style="margin-top:6px">Give this moment a name.</h2><div class="fields" style="margin-top:18px"><label>Class label<input id="captureLabel" value="${TB.task(p)==='anomaly'?'normal':'still'}" maxlength="40"></label><label>Session / group ID<input id="captureGroup" value="${esc('session-'+new Date().toISOString().slice(0,10))}" maxlength="80"></label><div class="field-pair"><label>Duration (seconds)<input id="duration" type="number" min="1" max="30" value="5"></label><label>Partition<select id="captureSplit"><option value="train">Training</option><option value="validation">Validation</option><option value="test">Test</option>${TB.task(p)==='anomaly'?'<option value="calibration">Calibration</option>':''}</select></label></div>${TB.task(p)==='regression'?'<label>Numeric target<input id="captureTarget" type="number" step="any" value="0"></label>':''}</div><div class="actions"><button id="recordBtn" class="primary" ${!serial.running||(!recording&&p.recovery)||device?.mode==='inference'?'disabled':''}>${recording?'Stop & keep recording':'Record example'}</button></div><p id="recordStatus" role="status" class="hint">Use a new session ID after changing subject, mounting, or collection conditions.</p></section>
 <section class="panel"><span class="eyebrow">GET THE BOARD READY</span><h3 style="margin-top:8px">Start with a capture sketch</h3><p class="hint">Upload with Arduino IDE. Open a new project before changing the channel schema.</p><label style="margin-top:13px">Sketch<select id="sketchKind"><option value="imu">Nano 33 BLE Sense Rev2 · IMU</option><option value="rev1">Nano 33 BLE Sense Rev1 · IMU</option><option value="iot">Nano 33 IoT · IMU</option><option value="analog">Any Arduino · analog A0</option></select></label><div class="actions"><button id="sketchBtn">Download capture ZIP</button><button id="audioProjectBtn">New audio project</button></div><p class="hint">IMU: ax, ay, az in g. A0: value in ADC counts. IMU ≤100 Hz; A0 ≤200 Hz. Each ZIP identifies its required sensor library.</p></section></aside></div>`;}
function datasetView(){
  if(!p.records.length)return pageHead('02 / MAKE GOOD EXAMPLES','The dataset is the foundation.','Labels describe what a recording means. Sessions describe where it came from.')+empty('An empty bench, ready for a signal.','Import a sensor recording, connect an Arduino, or load the demonstration.',`<button id="csvBtn" class="primary">Import CSV</button><button id="captureBtn">Capture data</button><button id="demoBtn">Load demonstration</button>`);
  let rs=p.records.filter(r=>(filter==='all'||r.split===filter)&&[r.name,r.label,r.group].join(' ').toLowerCase().includes(search.toLowerCase()));rs.sort((a,b)=>sort==='length'?b.rows.length-a.rows.length:a[sort].localeCompare(b[sort]));
  if(!selected||!p.records.some(r=>r.id===selected))selected=rs[0]?.id;const r=p.records.find(r=>r.id===selected);
  return pageHead('02 / MAKE GOOD EXAMPLES','Good models begin here.','Split by independent recording session before creating windows. Keep related recordings together.',`<button id="csvBtn">Import CSV</button><button id="splitBtn">Auto-split sessions</button><button id="trainTabBtn" class="primary">Design & train →</button>`)+`
  ${revisionsView()}<div class="grid dataset-layout"><section class="panel"><div class="toolbar"><input id="searchRecords" aria-label="Search recordings" placeholder="Find a label, recording, or session…" value="${esc(search)}"><select id="filterRecords" aria-label="Filter by partition">${['all',...partitions()].map(s=>`<option value="${s}" ${filter===s?'selected':''}>${s==='all'?'All partitions':s}</option>`).join('')}</select><select id="sortRecords" aria-label="Sort recordings">${[['name','Name'],['label','Label'],['length','Longest first']].map(([v,n])=>`<option value="${v}" ${sort===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="table-wrap"><table class="data-table"><thead><tr><th scope="col">Recording / session</th><th scope="col">Class</th><th scope="col">Length</th><th scope="col">Partition</th></tr></thead><tbody>${rs.map(r=>`<tr class="${r.id===selected?'selected':''}"><td><button class="select-record" data-id="${esc(r.id)}">${esc(r.name)}</button><span class="sub">${esc(r.group)}</span></td><td>${esc(r.label)}</td><td>${(r.rows.length/p.sampleRate).toFixed(2)} s</td><td>${badge(r.split)}</td></tr>`).join('')}</tbody></table></div>${rs.length?'':'<p class="hint">No recordings match this view.</p>'}<div class="stat-row">${splitStats()}</div><p class="hint">Auto-split aims for 60% training, 20% validation, 20% test by session. It requires at least 3 sessions per label or label combination. More data and varied collection conditions matter more than the ratio.</p></section>
  <aside class="panel inspector">${r?`<div class="panel-head"><h2>Recording inspector</h2><span class="eyebrow">${r.rows.length} ROWS</span></div><div class="scope"><canvas id="recordCanvas" role="img" aria-label="Selected recording waveform"></canvas></div><div class="scope-caption">${p.axes.map(a=>esc(a.name)+' ['+esc(a.unit)+']').join(' · ')}</div><div class="fields"><label>Name<input id="editName" value="${esc(r.name)}" maxlength="160"></label><label>Class label<input id="editLabel" value="${esc(r.label)}" maxlength="40"></label>${TB.task(p)==='regression'?`<label>Numeric target<input id="editTarget" type="number" step="any" value="${r.target}"></label>`:''}<label>Session / group<input id="editGroup" value="${esc(r.group)}" maxlength="80"></label><label>Partition<select id="editSplit">${partitions().map(s=>`<option ${s===r.split?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="actions"><button id="applyRecord" class="primary">Apply changes</button><button id="recordCSV">CSV</button><button id="deleteRecord" class="danger">Delete</button></div><p class="hint">Changing a partition moves every recording in the destination session. Trained models retain their original snapshots.</p><details><summary>Source</summary><p class="hint">${esc(r.source||'Imported recording')}</p>${r.capture?diagnosticsHTML(TBAcquisition.analyze(r,p.sampleRate)):'<p class="hint">No device diagnostics saved with this recording.</p>'}</details>`:'<p>Select a recording to inspect its signal and label.</p>'}</aside></div>`;
}
function audioProject(){const next=TB.fresh();next.name='Untitled audio project';next.axes=[{name:'audio',unit:'FS'}];next.sampleRate=16000;next.config.features='audio';next.config.window=8192;next.assumptions='Mono audio normalized to full scale at 16 kHz. Keep microphone gain, distance, environment, and preprocessing consistent. Include background/unknown classes and reserve independent recording sessions.';return next;}
function audioCaptureView(){const draft=p.audioDraft,ready=!!draft;return pageHead('01 / LISTEN AND LABEL','Teach it what to listen for.','Import a WAV or record a short clip. Label regions and keep regions from the same source session together.',`<button id="demoBtn">Try the audio demonstration</button><button id="sensorProjectBtn">New sensor project</button>`)+`<div class="grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>Audio input</h2><span class="badge">MONO · 16 kHz</span></div><div class="actions"><button id="wavBtn" class="primary" ${microphone.active?'disabled':''}>Import WAV</button><input id="wavFile" type="file" accept=".wav,audio/wav" hidden><button id="micBtn" ${(!isSecureContext||!navigator.mediaDevices?.getUserMedia||micBusy)?'disabled':''}>${microphone.active?'Stop microphone':'Record microphone'}</button><button id="pdmSketchBtn">Download Nano Sense microphone sketch</button></div><p id="micStatus" class="hint" role="status">${microphone.active?'Recording microphone · maximum 20 seconds':'WAV: PCM16/24/32 or float32, mono/stereo, 8–96 kHz, up to 20 seconds. Stereo is averaged; other rates are resampled to 16 kHz.'}</p>${!isSecureContext?'<p class="hint">Microphone access requires HTTPS or localhost. WAV import works here.</p>':''}<p class="hint">Arduino microphone capture sketch streams PCM packets. Connect it below, then record a board clip. Upload and close Serial Monitor first.</p><div class="actions"><button id="connectBtn" ${!navigator.serial||!isSecureContext?'disabled':''}>${serial.running?'Disconnect USB':'Connect Arduino'}</button><button id="boardAudioBtn" ${!serial.running||device?.mode!=='audio'?'disabled':''}>${boardAudio?'Stop board clip':'Record board clip'}</button></div><p id="boardAudioStatus" class="hint">${device?esc(device.board+' · '+device.mode):'No identified audio device'}</p></section><section class="panel"><h2>${draft?esc(draft.name):'A clip becomes labeled examples.'}</h2>${draft?`<div class="scope"><canvas id="audioCanvas" role="img" aria-label="Audio waveform with selected region"></canvas></div><audio id="audioPlayback" controls style="width:100%"></audio><p class="hint">${esc(draft.source)} · ${draft.sourceRate} Hz source · ${draft.channels} channel(s) · ${num(draft.samples.length/16000,3)} s. ${esc(draft.processing)}</p>${draft.problems?.length?'<p class="callout">Capture has missing PCM data; collect a clean clip. '+esc(draft.problems.join('; '))+'</p>':''}<p class="hint">The source clip is saved as an editable draft. Each accepted region becomes its own recording. Regions from one source cannot be split across training, validation, or test.</p>`:'<p class="hint">Start with the synthetic tone/event demonstration, or collect your own sound classes. Use independent clips and recording conditions; tone classification is not a speech benchmark.</p>'}</section></div><aside class="stack"><section class="panel olive"><h2>Label a region</h2><div class="fields"><div class="field-pair"><label>Start (seconds)<input id="audioStart" type="number" min="0" step=".001" value="${draft?.start??0}" ${!ready?'disabled':''}></label><label>End (seconds)<input id="audioEnd" type="number" min="0" step=".001" value="${draft?.end??0}" ${!ready?'disabled':''}></label></div><label>Label<input id="audioLabel" maxlength="40" value="${esc(draft?.label||'sound')}" ${!ready?'disabled':''}></label><label>Session / group<input id="audioGroup" maxlength="80" value="${esc(draft?.group||'')}" ${!ready?'disabled':''}></label><label>Partition<select id="audioSplit" ${!ready?'disabled':''}>${partitions().map(v=>`<option ${v===(draft?.split||'train')?'selected':''}>${v}</option>`).join('')}</select></label>${TB.task(p)==='regression'?`<label>Numeric target<input id="audioTarget" type="number" step="any" value="${draft?.target??0}"></label>`:''}</div><div class="actions"><button id="saveAudioRegion" class="primary" ${!ready?'disabled':''}>Keep labeled region</button><button id="clearAudioDraft" ${!ready?'disabled':''}>Clear clip draft</button></div><p class="hint">The current model window is ${num(p.config.window/16000,3)} s. Training uses only full windows inside each region.</p></section><section class="panel"><h2>Recorded examples</h2><div class="stat-row">${splitStats()}</div><button id="datasetBtn">Review dataset →</button></section></aside></div>`;}
function prepareAudio(audio,name){if(audio.samples.length<512)throw new Error('Capture is shorter than 32 ms. Try again.');p.audioDraft={...audio,samples:Array.from(audio.samples),name:String(name).slice(0,120),start:0,end:audio.samples.length/16000,label:TB.task(p)==='anomaly'?'normal':'sound',group:audio.origin,split:'train',target:0};requestSave();render();}
function audioDraftFields(){const d=p.audioDraft;if(!d)return;for(const[key,id]of [['start','audioStart'],['end','audioEnd'],['target','audioTarget']])if($('#'+id))d[key]=Number($('#'+id).value);for(const[key,id]of [['label','audioLabel'],['group','audioGroup'],['split','audioSplit']])d[key]=$('#'+id).value.trim();requestSave();paintAudio();}
async function stopMic(){if(!microphone.active||micBusy)return;micBusy=true;try{const clip=await microphone.stop();prepareAudio(clip,'Microphone '+new Date().toLocaleTimeString());}finally{micBusy=false;render();}}
function paintAudio(){const d=p.audioDraft;if(!d||!$('#audioCanvas'))return;const step=Math.max(1,Math.ceil(d.samples.length/800));drawSignal('audioCanvas',d.samples.filter((_,i)=>i%step===0).map(v=>[v]));const canvas=$('#audioCanvas'),ctx=canvas.getContext('2d'),scale=Math.min(devicePixelRatio||1,2),w=canvas.width/scale,h=canvas.height/scale;ctx.fillStyle='rgba(190,139,66,.18)';ctx.fillRect(d.start*16000/d.samples.length*w,0,(d.end-d.start)*16000/d.samples.length*w,h);if(audioObjectId!==d.origin){if(audioObjectURL)URL.revokeObjectURL(audioObjectURL);audioObjectURL=URL.createObjectURL(new Blob([TBAudio.encodeWAV(d.samples)],{type:'audio/wav'}));audioObjectId=d.origin;}if($('#audioPlayback').getAttribute('src')!==audioObjectURL)$('#audioPlayback').src=audioObjectURL;}
async function loadAudioDemo(){const next=audioProject();next.name='Three sounds to recognize';next.evidence='Synthetic tones and pulsed sounds. A software workflow fixture, not a speech-recognition or field-performance claim.';TBAudio.demo().forEach((d,i)=>next.records.push({id:'audio-demo-'+i,name:d.label+' '+(i%6+1),label:d.label,group:d.group,split:'train',source:'Synthetic audio demonstration',rows:Array.from(d.samples,v=>[v]),audio:{origin:d.group,sourceRate:16000,channels:1,start:0,end:d.samples.length}}));TB.partition(next.records,42);if(await replaceProject(next))go('dataset');}

function featureName(c){return ({stats:'Six time-domain statistics',spectral:'Statistics + Hann FFT bands',audio:'Framed audio spectrum'})[c.features||'stats'];}
function metricLabel(r,m=r.validation){return TB.task(r)==='regression'?'MAE '+num(m?.mae,4):pct(m?.accuracy);}
function trainView(){const run=activeRun(),mode=TB.task(p),audio=p.config.features==='audio';return pageHead('03 / FIND A PATTERN','A little intelligence, trained here.',`Task: ${mode}. Features and fitting run locally in a background worker.`)+`<div class="pipeline"><div><span class="eyebrow">WINDOW</span><span class="num">${p.config.window} samples</span><small>${num(p.config.window/p.sampleRate,3)} seconds</small></div><div><span class="eyebrow">FEATURES</span><span class="num">${TB.featureCount(p.axes.length,p.config)} values</span><small>${featureName(p.config)}</small></div><div><span class="eyebrow">TASK</span><span class="num">${mode}</span><small>${mode==='anomaly'?'Normal fit + separate calibration':mode==='regression'?'One numeric estimate':'One score per class'}</small></div></div><div class="grid"><section class="panel"><h2>Training recipe</h2><div class="controls"><label>Features<select id="featuresConfig" ${training||audio?'disabled':''}><option value="stats" ${!p.config.features||p.config.features==='stats'?'selected':''}>Time statistics</option><option value="spectral" ${p.config.features==='spectral'?'selected':''}>Statistics + frequency bands</option>${audio?'<option value="audio" selected>Framed audio spectrum</option>':''}</select></label><label>Window size<select id="windowConfig" ${training?'disabled':''}>${(audio?[512,1024,2048,4096,8192,16384]:[16,32,64,128,256]).map(n=>`<option value="${n}" ${n===p.config.window?'selected':''}>${n} samples · ${num(n/p.sampleRate,3)} s</option>`).join('')}</select></label><label>Overlap<select id="overlapConfig" ${training?'disabled':''}><option value="0" ${p.config.overlap===0?'selected':''}>None</option><option value="0.5" ${p.config.overlap===.5?'selected':''}>50% within each recording</option></select></label>${mode!=='anomaly'?`<label>Model<select id="hiddenConfig" ${training?'disabled':''}>${[[0,mode==='regression'?'Linear regression':'Linear softmax'],[12,'12 ReLU neurons'],[24,'24 ReLU neurons']].map(([v,n])=>`<option value="${v}" ${p.config.hidden===v?'selected':''}>${n}</option>`).join('')}</select></label>`:`<label>Normal calibration quantile<input id="anomalyQuantileConfig" type="number" min=".9" max="1" step=".01" value="${p.config.anomalyQuantile??.99}" ${training?'disabled':''}></label>`}</div><details class="advanced"><summary>Advanced fitting controls</summary><div class="controls">${[['epochs','Maximum epochs',10,400,1],['rate','Learning rate',.0001,.1,.0001],['seed','Random seed',0,2147483647,1]].map(([key,label,min,max,step])=>`<label>${label}<input id="${key}Config" type="number" min="${min}" max="${max}" step="${step}" value="${p.config[key]}" ${training||mode==='anomaly'?'disabled':''}></label>`).join('')}</div></details><p class="hint">${mode==='anomaly'?'Fit the normal-data center and spread using training only. Choose the threshold from separate normal calibration sessions; use validation and test sessions containing both normal and unusual behavior. Scores are distances, not probabilities.':'Training-only normalization; Adam batches of 32; validation loss selects the best epoch. Test data never fits weights or normalization.'}</p><div class="actions"><button id="trainBtn" class="primary" ${training||!p.records.length?'disabled':''}>${training?'Training…':'Train model'}</button>${training?'<button id="cancelTrain">Cancel training</button>':'<button id="datasetBtn">Review data</button>'}${run?'<button id="testTabBtn">Inspect & test →</button>':''}</div><div class="progress-track"><div id="trainProgress" style="width:${progress?100*progress.epoch/progress.total:0}%"></div></div><p id="trainingStatus" role="status" class="hint">${progress?'Training progress saved in the current run.':'Previous model runs remain available. Interrupted training can be restarted from its saved recipe.'}</p><div class="scope"><canvas id="lossCanvas" role="img" aria-label="Training and validation loss"></canvas></div><p class="hint">${mode==='anomaly'?'Anomaly fitting is closed-form; no epoch curve.':mode==='regression'?'Mean squared error · lower is better':'Cross-entropy loss · lower is better'}</p></section><aside class="stack"><section class="panel"><h2>Data readiness</h2><div class="stat-row">${splitStats()}</div><p class="hint">${mode==='anomaly'?'Use at least four independent normal sessions and two anomaly sessions for automatic splitting.':'Each partition needs complete windows; keep related recordings in the same session.'} Exact duplicates across partitions are blocked.</p></section><section class="panel"><h2>Training notebook</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Run / task</th><th>Validation</th></tr></thead><tbody>${p.runs.slice().reverse().map(r=>`<tr><td><button class="select-run" data-id="${esc(r.id)}">${esc(r.id)}</button><span class="sub">${TB.task(r)} · ${featureName(r.config)} ${p.baseline===r.id?'· baseline':''}</span></td><td>${metricLabel(r)}</td></tr>`).join('')}</tbody></table></div><p class="hint">Up to eight runs; the oldest non-baseline run is replaced. Save JSON to archive the full notebook.</p></section></aside></div>`;}
function metricsView(run,m){const reg=TB.task(run)==='regression';return `<div class="metrics">${(reg?[[num(m.mae,4),'Mean absolute error'],[num(m.rmse,4),'Root mean square error'],[num(m.r2,3),'R²']]:[[pct(m.accuracy),'Window accuracy'],[num(m.macroF1,3),'Macro F1'],[m.count,'Windows']]).map(([v,n])=>`<div class="metric"><strong>${v}</strong><small>${n}</small></div>`).join('')}</div>${reg?`<p class="hint">Target units: ${esc(run.target?.unit||'not specified')}. R² is undefined when all reference targets are equal.</p>`:`<div class="table-wrap"><table class="confusion"><caption>Actual rows / predicted columns</caption><thead><tr><th>Class</th>${run.labels.map(l=>`<th>${esc(l)}</th>`).join('')}</tr></thead><tbody>${m.cm.map((row,i)=>`<tr><th>${esc(run.labels[i])}</th>${row.map((n,j)=>`<td class="${i===j?'diagonal':''}">${n}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Class</th><th>Precision</th><th>Recall</th><th>F1</th><th>Windows</th></tr></thead><tbody>${m.classes.map((c,i)=>`<tr><td>${esc(run.labels[i])}</td><td>${pct(c.precision)}</td><td>${pct(c.recall)}</td><td>${num(c.f1,3)}</td><td>${c.support}</td></tr>`).join('')}</tbody></table></div>`}${m.sessions?`<details><summary>Session-level evidence · ${m.sessions.count} sessions</summary><p class="hint">Each session has equal weight: ${reg?'mean session MAE '+num(m.sessions.meanMAE,4):'mean session accuracy '+pct(m.sessions.meanAccuracy)}. Windows within a session may be correlated.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Session</th><th>Windows</th><th>${reg?'MAE':'Accuracy'}</th></tr></thead><tbody>${m.sessions.rows.map(s=>`<tr><td>${esc(s.group)}</td><td>${s.count}</td><td>${reg?num(s.mae,4):pct(s.accuracy)}</td></tr>`).join('')}</tbody></table></div></details>`:'<p class="hint">This older run has no saved session metrics.</p>'}`;}
function testView(){const run=activeRun();if(!run)return pageHead('04 / CHALLENGE THE MODEL','Good scores need good evidence.','Train a model before examining its validation and held-out test results.')+empty('No trained model yet.','Your raw data remains on this device.','<button id="trainTabBtn" class="primary">Train a model</button>');const available=p.records.filter(r=>r.rows.length>=run.config.window&&JSON.stringify(p.axes)===JSON.stringify(run.axes)&&p.sampleRate===run.sampleRate&&(run.test||r.split!=='test'));if(!available.some(r=>r.id===replayId))replayId=available.find(r=>r.split==='validation')?.id||available[0]?.id;const replay=available.find(r=>r.id===replayId);replayOffset=Math.min(replayOffset,Math.max(0,(replay?.rows.length||0)-run.config.window));return pageHead('04 / CHALLENGE THE MODEL','Good scores need good evidence.','Settle the recipe using validation, then evaluate independent held-out sessions.','<button id="reportBtn">Print / PDF report</button><button id="exportTabBtn" class="primary">Prepare Arduino export →</button>')+runSelector()+staleCallout(run)+`<div class="grid"><div class="stack"><section class="panel"><h2>${run.test?'Held-out test':'Validation · test pending'}</h2>${metricsView(run,run.test||run.validation)}<div class="actions"><button id="evaluateBtn" class="primary" ${stale(run)?'disabled':''}>${run.test?'Re-evaluate held-out test':'Evaluate held-out test'}</button><button id="baselineBtn">${p.baseline===run.id?'Clear baseline':'Set as baseline'}</button></div><div class="callout"><strong>Review · confidence limited</strong><p>Independent sessions matter more than window count. Synthetic examples verify the workflow; they do not establish field performance. Repeated tuning against test results requires a new final test set.</p></div>${run.calibration?`<p class="hint">Threshold ${num(run.calibration.threshold,4)} from ${run.calibration.count} normal calibration windows; quantile ${run.calibration.quantile}. Calibration groups: ${run.calibration.groups.map(esc).join(', ')}.</p>`:''}</section>${baselineView(run)}</div><aside class="panel"><h2>Replay a recording</h2><label>Input<select id="replaySelect">${available.map(r=>`<option value="${esc(r.id)}" ${r.id===replayId?'selected':''}>${esc(r.name)} · ${r.split}</option>`).join('')}</select></label>${replay?`<label>Window start · <span id="offsetLabel">${num(replayOffset/run.sampleRate,3)} s</span><input id="replayOffset" type="range" min="0" max="${replay.rows.length-run.config.window}" value="${replayOffset}" step="1"></label><div class="scope"><canvas id="replayCanvas" role="img" aria-label="Replay window waveform"></canvas></div><div id="predictionScores"></div>`:'<p class="hint">No available recording matches this model schema.</p>'}${TB.task(run)==='classification'?`<div class="threshold"><label for="threshold">Uncertain below <span id="thresholdValue">${Math.round(p.threshold*100)}%</span></label><input id="threshold" type="range" min=".1" max="1" step=".01" value="${p.threshold}"></div><p class="hint">Scores are not calibrated confidence. The uncertain threshold is not an unknown-class detector.</p>`:''}</aside></div>`;}
function baselineView(run){const base=p.runs.find(r=>r.id===p.baseline);if(!base)return '';const same=TB.task(base)===TB.task(run)&&((base.dataSignature&&run.dataSignature)?base.dataSignature===run.dataSignature:base.signature===run.signature);return `<section class="panel"><h2>Baseline comparison</h2><p class="hint">${same?'Same task and dataset; recipes may differ.':'Different task or dataset, or an older run without a dataset fingerprint. Treat this as descriptive, not a controlled model comparison.'}</p><table class="data-table"><thead><tr><th>Measure</th><th>Baseline</th><th>Active</th></tr></thead><tbody><tr><td>Validation</td><td>${metricLabel(base)}</td><td>${metricLabel(run)}</td></tr><tr><td>Test</td><td>${base.test?metricLabel(base,base.test):'pending'}</td><td>${run.test?metricLabel(run,run.test):'pending'}</td></tr><tr><td>Float constants</td><td>${TBExport.memory(base).constants} B</td><td>${TBExport.memory(run).constants} B</td></tr></tbody></table></section>`;}
function revisionsView(){return `<details class="panel" style="margin-bottom:20px"><summary>Dataset revisions · ${(p.revisions||[]).length} / 3 saved</summary><p class="hint">Freeze raw recordings, labels, partitions, and recipe before experimenting. Restore keeps saved model runs and marks mismatches as stale.</p><div class="actions"><input id="revisionName" aria-label="Revision name" maxlength="80" placeholder="Before changing labels"><button id="saveRevision">Save revision</button></div>${(p.revisions||[]).map(r=>`<div class="actions"><span>${esc(r.name)} · ${r.snapshot.records.length} recordings</span><button class="restore-revision" data-id="${esc(r.id)}">Restore</button><button class="export-revision" data-id="${esc(r.id)}">Download</button></div>`).join('')}</details>`;}
function report(){const r=activeRun();if(!r)throw new Error('Train a model before creating a report.');const mem=TBExport.memory(r);$('#printReport').innerHTML=`<div class="print-meta">GREEN SHOE GARAGE · TINYBENCH v${TB.VERSION}</div><h1>${esc(r.name)}</h1><p>Run ${esc(r.id)} · ${esc(r.created)} · ${TB.task(r)}</p><h2>Recipe</h2><p>${featureName(r.config)} · ${r.config.window} samples at ${r.sampleRate} Hz · ${r.config.overlap*100}% overlap. Channels: ${r.axes.map(a=>esc(a.name)+' ['+esc(a.unit)+']').join(', ')}. Signature ${esc(r.signature)} (noncryptographic change detector).</p><h2>${r.test?'Held-out test':'Validation only — test pending'}</h2>${metricsView(r,r.test||r.validation).replaceAll('<details>','<details open>')}<h2>Findings · review · confidence limited</h2><p>Metrics describe the saved model run. Overlapping windows are correlated; use independent collection sessions. ${stale(r)?'The current dataset or recipe differs from this run.':''} Synthetic results demonstrate workflow only.</p><h2>Assumptions (current project)</h2><p>${esc(p.assumptions)}</p><h2>Evidence (current project)</h2><p>${esc(p.evidence)||'No field evidence recorded.'}</p><h2>Acquisition and deployment</h2><p>${p.records.filter(x=>x.capture).length} current recordings include serial timing provenance. ${p.recovery?'A pending interrupted capture remains excluded.':''} ${mem.constants} bytes of float constants; ${mem.working} bytes of principal buffers, including DSP scratch. Estimates exclude runtime/core/sensor overhead and any extra streaming buffers. Physical board validation remains required.</p>`;window.print();}

function runSelector(){return `<div class="model-heading"><div><span class="eyebrow">ACTIVE MODEL</span><h2>${esc(activeRun()?.name||'No trained model')}</h2></div><label class="sr-only" for="runSelect">Select model run</label><select id="runSelect">${p.runs.slice().reverse().map(r=>`<option value="${esc(r.id)}" ${r.id===p.activeRun?'selected':''}>${esc(r.id)} · ${TB.task(r)==='anomaly'?'Normal-distance':r.config.hidden?'NN '+r.config.hidden:'Linear'} · ${metricLabel(r)} validation</option>`).join('')}</select></div>`;}
function staleCallout(run){return stale(run)?'<div class="callout error"><strong>Project changed since this run.</strong><p>These results belong to the saved run. Retrain before testing the current dataset. Export still uses the run’s original features and weights.</p></div>':'';}
function exportView(){const run=activeRun();if(!run)return pageHead('05 / PUT IT TO WORK','Intelligence belongs on the device.','Export your learned pattern as a small Arduino library, with the preprocessing included.')+empty('Your first model is one training run away.','The export contains the feature extractor, normalization, learned weights, and a test sketch.',`<button id="trainTabBtn" class="primary">Train a model →</button>`);const mem=TBExport.memory(run);
 return pageHead('05 / PUT IT TO WORK','From this bench to your board.','A portable Arduino library. Your data, your model, your hardware.',`<button id="reportBtn">Print / PDF report</button><button id="backupProject">Save project JSON</button>`)+runSelector()+staleCallout(run)+`
 <div class="grid" style="margin-top:20px"><div class="stack"><section class="panel download-panel"><span class="eyebrow">ARDUINO LIBRARY / C++</span><h2 style="margin-top:10px">The whole signal-to-decision pipeline.</h2><p>${featureName(run.config)}, fitted normalization, your trained ${TB.task(run)} model, and a repeatable test input. No machine-learning runtime or online service required for inference.</p><button id="libraryBtn" class="primary">Download Arduino library .zip ↓</button><small>${run.config.window} samples · ${run.axes.length} channels · ${TB.task(run)} · ${TB.task(run)==='anomaly'?'normal-distance detector':run.config.hidden?'neural network / '+run.config.hidden+' hidden neurons':TB.task(run)==='regression'?'linear regression':'linear softmax'}</small></section><section class="panel"><h2>Bring-up, in four steps</h2><ol class="guide-steps"><li>In Arduino IDE, use <strong>Sketch → Include Library → Add .ZIP Library</strong>.</li><li>Select your board, then open <strong>File → Examples → TinyBenchModel → StaticBuffer</strong>.</li><li>Upload and open Serial Monitor at <strong>115200 baud</strong>. Compare the output with the fixed example input saved in model.json.</li><li>Connect your sensor and feed windows using the same <strong>channel order, units, and ${run.sampleRate} Hz sample rate</strong>. Buffered Nano Sense examples are included for classifiers when the model uses ax/ay/az in g at ≤100 Hz.</li></ol><div class="callout"><strong>Physical verification remains required.</strong><p>This download contains source. The optional local worker can compile StaticBuffer and return binaries. Check compiler memory use, sensor timing, and inference latency on the board. Buffered IMU examples collect in a separate task and report sampling/queue losses.</p></div></section><section class="panel"><div class="panel-head"><h2>Preserve the experiment</h2><span class="eyebrow">REPRODUCIBLE OUTPUTS</span></div><div class="actions"><button id="modelJSON">Model JSON</button><button id="reportBtn2">Print / PDF report</button><button id="backupProject2">Full project JSON</button></div><p class="hint">Model JSON contains the recipe, metrics, recording manifest, weights, and one input fixture. Full project JSON also contains raw recordings and the training notebook.</p></section></div>
 <aside class="stack"><section class="panel"><span class="eyebrow">TARGET HARDWARE</span><label style="margin-top:14px">Board family<select id="boardSelect">${Object.entries(boardNames).map(([k,v])=>`<option value="${k}" ${p.board===k?'selected':''}>${v}</option>`).join('')}</select></label><p class="hint" id="boardHint">${boardHint()}</p><div class="memory"><div><strong>${(mem.constants/1024).toFixed(2)} KB</strong><small>Float constants</small></div><div><strong>${(mem.working/1024).toFixed(2)} KB</strong><small>Working buffers</small></div></div><p class="hint">Estimates, not profiling. Excludes firmware code, labels, stack, sensor libraries, and example data. Buffered examples additionally allocate three input windows plus a 4 KB sampler stack and RTOS metadata. Some cores also place constants in RAM. The board selector records your target; it does not compile or optimize for that board.</p><ul class="checks"><li><span class="symbol">✓</span><span>Features and normalization included</span></li><li><span class="${run.test?'symbol':'warn'}">${run.test?'✓':'!'}</span><span>${run.test?'Held-out test evaluated':'Held-out test not yet evaluated'}</span></li><li><span class="warn">!</span><span>Physical board tests not performed</span></li></ul></section><details class="panel"><summary>Release scope and next steps</summary><p class="hint">v1.0 includes local sensor/audio classification, regression, anomaly scoring, dataset revisions, recovery, native C++ export, and an optional training/build worker. See the release's BOARD-MATRIX and VERIFICATION documents for exact compile evidence.</p><p class="hint">Physical Arduino qualification, measured sustained latency, and TensorFlow Lite Micro firmware qualification remain pending. Camera models and shared project storage are future work.</p></details></aside></div>`;
}
function boardHint(){return p.board==='nano33'?'The supplied IMU capture and inference examples target the Nano 33 BLE Sense Rev2 with Arduino_BMI270_BMM150. Rev1 needs a different sensor adapter.':p.board==='other'?'Export uses portable C++ and standard math functions. Small AVR boards may lack enough RAM for the window and model; use a smaller window or a larger board.':'Use the StaticBuffer example first. Supply your own sensor adapter for this board, or use the generic A0 capture sketch for a one-channel project.';}
function trainingRecoveryView(){return `<section class="panel recovery"><h2>Training was interrupted</h2><p>The saved recipe and previous models are intact. Restart repeats training from its seed; partial weights are not resumed.</p><div class="actions"><button id="restartTraining" ${TB.dataSignature(p)!==p.trainingJob.dataSignature?'disabled':''}>Restart saved recipe</button><button id="dismissTrainingRecovery">Dismiss</button></div></section>`;}
function bindView(){bind('restartTraining','click',()=>{p.config=TB.clone(p.trainingJob.config);return startTraining();});bind('dismissTrainingRecovery','click',()=>{p.trainingJob=null;requestSave();render();});
  bind('audioProjectBtn','click',async()=>{if(await replaceProject(audioProject()))go('capture');});bind('sensorProjectBtn','click',async()=>{if(await replaceProject(TB.fresh()))go('capture');});
  bind('wavBtn','click',()=>{$('#wavFile').click();});bind('wavFile','change',async e=>{guardTraining();const f=e.target.files[0];if(!f)return;prepareAudio(TBAudio.decodeWAV(await f.arrayBuffer()),f.name);});
  bind('micBtn','click',async()=>{if(microphone.active)return stopMic();guardTraining();micBusy=true;render();try{await microphone.start(seconds=>{if($('#micStatus'))$('#micStatus').textContent='Recording '+num(seconds,1)+' / 20 s';},()=>safe(stopMic)());}finally{micBusy=false;render();}});
  for(const id of ['audioStart','audioEnd','audioLabel','audioGroup','audioSplit','audioTarget'])bind(id,'change',audioDraftFields);
  bind('saveAudioRegion','click',()=>{guardTraining();audioDraftFields();if(p.audioDraft.problems?.length)throw new Error('This clip has missing PCM data. Collect a clean clip before training.');const d=p.audioDraft,region=TBAudio.region({...d,samples:Float32Array.from(d.samples)},d.start,d.end);addRecord({id:uid(),name:d.label+' · '+num(d.start,2)+'–'+num(d.end,2)+' s',label:d.label,group:d.group,split:d.split,target:d.target,source:d.source+' · '+d.name,...region});render();notify('Labeled region saved. Choose another region or review the dataset.');});
  bind('clearAudioDraft','click',()=>{if(confirm('Clear this source clip draft? Saved labeled regions remain in the dataset.')){p.audioDraft=null;requestSave();render();}});
  bind('pdmSketchBtn','click',()=>download(TBExport.zip({'TinyBenchPDM/TinyBenchPDM.ino':TBFirmware.pdmCapture()}),'TinyBenchPDM.zip'));
  bind('boardAudioBtn','click',()=>{if(boardAudio)finishBoardAudio();else{guardTraining();if(device?.mode!=='audio')throw new Error('Connect the PDM capture sketch first.');boardAudio={samples:[],lastSeq:null,problems:[],started:Date.now()};boardAudioTimer=setTimeout(finishBoardAudio,20000);render();}});

  bind('saveRevision','click',()=>{guardTraining();if(!p.records.length)throw new Error('Add recordings first.');const name=$('#revisionName').value.trim()||'Dataset '+new Date().toLocaleString();if((p.revisions||[]).length>=3&&!confirm('Replace the oldest dataset revision? Download it first if needed.'))return;const revisions=(p.revisions||[]).slice(-2),revision=TB.revision(p,name);if(JSON.stringify({...p,revisions:[...revisions,revision]}).length>120*1024*1024)throw new Error('Revision would exceed the portable project limit. Export JSON before adding more snapshots.');p.revisions=[...revisions,revision];requestSave();render();});
  $$('.restore-revision').forEach(b=>b.onclick=safe(()=>{guardTraining();const rev=p.revisions.find(r=>r.id===b.dataset.id);if(confirm('Restore this dataset and recipe? Save JSON first to preserve current edits.')){p=TB.restoreRevision(p,rev);selected=null;requestSave();render();}}));
  $$('.export-revision').forEach(b=>b.onclick=()=>{const rev=p.revisions.find(r=>r.id===b.dataset.id);const project=TB.restoreRevision(TB.fresh(),rev);download(JSON.stringify(project,null,2),'TinyBench-'+rev.id+'.json');});

  for(const [id,dest] of [['captureBtn','capture'],['datasetBtn','dataset'],['trainTabBtn','train'],['testTabBtn','test'],['exportTabBtn','export']])bind(id,'click',()=>go(dest));
  bind('demoBtn','click',loadDemo);bind('csvBtn','click',openCSV);bind('settingsBtn','click',openSettings);bind('connectBtn','click',async()=>{try{if(serial.running){if(recording)interruptCapture('USB disconnected by user.');await serial.disconnect();}else await serial.connect();}finally{render();}});
  bind('reconnectBtn','click',async()=>{try{await serial.connect(true);}finally{render();}});
  bind('useDevice','click',()=>{guardTraining();if(p.records.length||p.recovery)throw new Error('Start an empty project before changing channels.');if(!device||device.mode!=='capture')return;p.axes=TB.clone(device.axes);p.sampleRate=device.rate_hz;TB.validateProject(p);diagnostics=new TinyDiagnostics(p.sampleRate);latest=[];validCount=0;requestSave();render();});
  bind('exportRecovery','click',()=>download(JSON.stringify(p.recovery,null,2),fileBase()+'-interrupted-capture.json'));
  bind('discardRecovery','click',()=>{if(confirm('Discard this recovery capture? Download its raw data first if needed.')){p.recovery=null;requestSave();render();}});
  bind('keepRecovery','click',()=>{const d=p.recovery;TBAcquisition.validateDraft(d,p);const reason=TBAcquisition.quality(d.record,p.sampleRate);if(reason)throw new Error(reason);const r=TB.clone(d.record);r.capture.diagnostics=TBAcquisition.analyze(r,p.sampleRate);r.source+=' · recovered partial capture';addRecord(r);p.recovery=null;requestSave();render();notify('Clean partial capture kept as a separate recording.');});
  bind('recordBtn','click',()=>recording?finishRecording():startRecording());bind('sketchBtn','click',()=>{const kind=$('#sketchKind').value,a=TBFirmware.adapters[kind],name='TinyBenchCapture_'+kind;download(TBExport.zip({[name+'/'+name+'.ino']:TBExport.captureSketch(kind,p.sampleRate),[name+'/README.txt']:`TinyBench v${TB.VERSION}
Target: ${a.board}
Install: ${a.library||'No external sensor library'}
Upload with Arduino IDE. Close Serial Monitor, connect in TinyBench, inspect the identity and choose Use device settings in an empty project. ${p.sampleRate} Hz, 115200 baud. Physical-board qualification is pending. See docs/PROTOCOL.md in the TinyBench app release.`}),name+'.zip');});
  bind('splitBtn','click',()=>{guardTraining();const next=TB.clone(p.records);TB.partition(next,p.config.seed,TB.task(p));TB.validateProject({...p,records:next});p.records=next;requestSave();render();notify('Sessions split into training, validation, and held-out test.');});
  bind('searchRecords','input',e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#searchRecords').focus();$('#searchRecords').setSelectionRange(pos,pos);});bind('filterRecords','change',e=>{filter=e.target.value;render();});bind('sortRecords','change',e=>{sort=e.target.value;render();});
  $$('.select-record').forEach(b=>b.onclick=()=>{selected=b.dataset.id;render();});bind('applyRecord','click',editRecord);bind('deleteRecord','click',()=>{guardTraining();const r=p.records.find(r=>r.id===selected);if(confirm(`Delete “${r.name}”? Save a project backup first if you need to preserve this raw recording.`)){p.records=p.records.filter(x=>x.id!==selected);selected=null;requestSave();render();}});bind('recordCSV','click',()=>{const r=p.records.find(r=>r.id===selected);download(p.axes.map(a=>a.name).join(',')+'\n'+r.rows.map(row=>row.join(',')).join('\n'),r.name.replace(/[^A-Za-z0-9_-]/g,'-')+'.csv','text/csv');});
  for(const key of ['features','window','overlap','hidden','epochs','rate','seed','anomalyQuantile'])bind(key+'Config','change',e=>{guardTraining();const c={...p.config,[key]:key==='features'?e.target.value:Number(e.target.value)};TB.validateConfig(c);p.config=c;requestSave();const wasOpen=$('.advanced')?.open;render();if(wasOpen&&$('.advanced'))$('.advanced').open=true;});
  bind('trainBtn','click',startTraining);bind('cancelTrain','click',()=>{worker?.terminate();training=false;p.trainingJob=null;progress=null;requestSave();render();notify('Training cancelled. Previously saved models are unchanged.');});
  $$('.select-run').forEach(b=>b.onclick=()=>{p.activeRun=b.dataset.id;requestSave();render();});bind('runSelect','change',e=>{p.activeRun=e.target.value;replayOffset=0;requestSave();render();});
  bind('evaluateBtn','click',()=>{const r=activeRun();r.test=TB.evaluate(p,r);r.testedAt=new Date().toISOString();requestSave();render();notify('Held-out test evaluated. Test data was not used to fit this run.');});
  bind('baselineBtn','click',()=>{p.baseline=p.baseline===p.activeRun?null:p.activeRun;requestSave();render();});
  bind('replaySelect','change',e=>{replayId=e.target.value;replayOffset=0;render();});bind('replayOffset','input',e=>{replayOffset=Number(e.target.value);$('#offsetLabel').textContent=(replayOffset/activeRun().sampleRate).toFixed(2)+' s';paintReplay();});bind('threshold','input',e=>{p.threshold=Number(e.target.value);$('#thresholdValue').textContent=Math.round(p.threshold*100)+'%';requestSave();paintReplay();});
  for(const id of ['reportBtn','reportBtn2'])bind(id,'click',report);for(const id of ['backupProject','backupProject2'])bind(id,'click',backup);
  bind('libraryBtn','click',()=>{const r=activeRun();TB.validateRun(r);download(TBExport.zip(TBExport.library(r,p.threshold)),'TinyBenchModel-'+r.id+'.zip');notify('Arduino library exported. Start with the StaticBuffer example.');});bind('modelJSON','click',()=>download(JSON.stringify(activeRun(),null,2),'TinyBench-'+activeRun().id+'.json'));
  bind('boardSelect','change',e=>{p.board=e.target.value;requestSave();$('#boardHint').textContent=boardHint();});
}
function guardTraining(){if(microphone.active||micBusy||boardAudio)throw new Error('Stop the audio capture first.');if(training)throw new Error('Wait for training to finish or cancel it before changing the dataset.');if(recording)throw new Error('Finish the current capture before changing this project.');}
async function replaceProject(next){guardTraining();if(saveBlocked&&!restoreFailed)throw new Error('Another tab or a save error blocked autosave. Save JSON, then reload before replacing the project.');if(p.records.length||p.runs.length||p.recovery||p.audioDraft)if(!confirm('Replace the current project? Save JSON first to preserve it.'))return false;if(serial.running)await serial.disconnect();if(restoreFailed){saveBlocked=false;restoreFailed=false;}p=next;selected=null;replayId=null;replayOffset=0;search='';filter='all';latest=[];validCount=0;badRows=0;device=null;lastPrediction=null;diagnostics=new TinyDiagnostics(p.sampleRate);progress=null;requestSave();return true;}
async function loadDemo(){if(p.config.features==='audio')return loadAudioDemo();if(await replaceProject(TB.sample(TB.task(p)))){go('dataset');notify('Synthetic motion dataset loaded. Inspect it, then train your first classifier.');}}
function backup(){download(JSON.stringify(p,null,2),fileBase()+'.tinybench.json');notify('Project JSON exported with raw recordings and model history.');}
function openSettings(){const locked=p.records.length>0||training||!!recording||!!p.recovery||!!p.audioDraft||p.config.features==='audio';$('#taskInput').value=TB.task(p);$('#taskInput').disabled=locked;$('#targetUnitInput').value=p.targetUnit||'';$('#nameInput').value=p.name;$('#axesInput').value=p.axes.map(a=>a.name).join(',');$('#unitsInput').value=p.axes.map(a=>a.unit).join(',');$('#sampleRateInput').value=p.sampleRate;for(const id of ['axesInput','unitsInput','sampleRateInput'])$('#'+id).disabled=locked;$('#schemaHint').textContent=locked?'Schema is locked while recordings exist. Create a new project to change channels, units, or sample rate.':'Channel order, units, and rate must match your sensor firmware and CSVs.';$('#assumptionsInput').value=p.assumptions;$('#evidenceInput').value=p.evidence;$('#projectDialog').showModal();}
function applySettings(){guardTraining();const next=TB.clone(p),names=$('#axesInput').value.split(',').map(v=>v.trim()),units=$('#unitsInput').value.split(',').map(v=>v.trim());if(!$('#nameInput').value.trim())throw new Error('Give the project a name.');if(names.length!==units.length)throw new Error('Use one unit for each channel.');next.name=$('#nameInput').value.trim();if(!next.records.length&&!next.recovery)next.task=$('#taskInput').value;next.targetUnit=$('#targetUnitInput').value.slice(0,20);if(!next.records.length&&!next.recovery){next.axes=names.map((name,i)=>({name,unit:units[i]}));next.sampleRate=Number($('#sampleRateInput').value);}next.assumptions=$('#assumptionsInput').value;next.evidence=$('#evidenceInput').value;TB.validateProject(next);p=next;diagnostics=new TinyDiagnostics(p.sampleRate);latest=[];validCount=0;requestSave();$('#projectDialog').close();render();}
function openCSV(){guardTraining();$('#csvTargetWrap').hidden=TB.task(p)!=='regression';$('#csvSplit').innerHTML=partitions().map(v=>'<option>'+v+'</option>').join('');$('#csvLabel').value=TB.task(p)==='anomaly'?'normal':'still';$('#csvFile').value='';$('#csvGroup').value='session-'+Date.now().toString(36);$('#csvHint').textContent='Header: '+p.axes.map(a=>a.name).join(',')+' · Optional timestamp_ms column. '+p.sampleRate+' Hz.';$('#csvDialog').showModal();}
async function importCSV(){guardTraining();const f=$('#csvFile').files[0];if(!f)throw new Error('Select a CSV file.');if(f.size>10*1024*1024)throw new Error('CSV is too large (10 MB limit).');const{rows,observedRate}=TB.parseCSV(await f.text(),p.axes);if(observedRate&&Math.abs(observedRate-p.sampleRate)/p.sampleRate>.05)throw new Error(`CSV timestamps indicate ${observedRate.toFixed(2)} Hz; project is ${p.sampleRate} Hz. Use a matching project or resample the recording.`);const r={id:uid(),name:f.name.replace(/\.csv$/i,''),label:$('#csvLabel').value.trim(),group:$('#csvGroup').value.trim(),split:$('#csvSplit').value,target:TB.task(p)==='regression'?Number($('#csvTarget').value):undefined,source:'CSV: '+f.name+(observedRate?` · measured ${observedRate.toFixed(2)} Hz`:' · rate asserted by user'),rows};addRecord(r);$('#csvDialog').close();go('dataset');notify('Recording imported. Use independent sessions in each partition before training.');}
function addRecord(r){const next=TB.clone(p);next.records.push(r);TB.validateProject(next);p=next;selected=r.id;requestSave();}
function editRecord(){guardTraining();const next=TB.clone(p),r=next.records.find(x=>x.id===selected);r.name=$('#editName').value.trim();if(TB.task(p)==='regression')r.target=Number($('#editTarget').value);r.label=$('#editLabel').value.trim();r.group=$('#editGroup').value.trim();r.split=$('#editSplit').value;for(const x of next.records)if(x.group===r.group)x.split=r.split;TB.validateProject(next);p=next;requestSave();render();notify('Recording updated. Related session recordings use the same partition.');}
async function startTraining(){guardTraining();TB.dataset(p);if(location.protocol==='file:')throw new Error('Training uses a Web Worker. Serve this folder with python3 -m http.server 8000, then open http://localhost:8000.');p.trainingJob={status:'running',started:new Date().toISOString(),dataSignature:TB.dataSignature(p),config:TB.clone(p.config)};requestSave();clearTimeout(saveTimer);await save();if(saveBlocked)throw new Error('Save JSON and reload before starting another training run.');training=true;progress=null;worker=new Worker('./worker.js');let points=[];render();worker.onmessage=e=>{const msg=e.data;if(msg.type==='progress'){progress=msg.data;points.push(progress);if($('#trainProgress'))$('#trainProgress').style.width=100*progress.epoch/progress.total+'%';if($('#trainingStatus'))$('#trainingStatus').textContent=`Epoch ${progress.epoch}/${progress.total} · validation loss ${progress.valLoss.toFixed(4)} · accuracy ${pct(progress.valAccuracy)}`;drawLoss(points);}else if(msg.type==='done'){training=false;p.trainingJob=null;const r=msg.data;while(p.runs.length>=8){const i=p.runs.findIndex(x=>x.id!==p.baseline);p.runs.splice(i,1);}p.runs.push(r);p.activeRun=r.id;worker.terminate();requestSave();render();notify(`Training complete. Validation: ${metricLabel(r)}. Test set is still untouched.`);}else{training=false;p.trainingJob.status='interrupted';worker.terminate();requestSave();render();notify(msg.message,true);}};worker.onerror=e=>{training=false;if(p.trainingJob)p.trainingJob.status='interrupted';worker.terminate();requestSave();render();notify('Training worker failed. Serve all app files from one origin and retry. '+e.message,true);};worker.postMessage(TB.clone(p));}
function acquisitionPanel(){return `<section class="panel"><div class="panel-head"><div><span class="eyebrow">ACQUISITION QUALITY</span><h2>Know what arrived.</h2></div><span class="badge">Protocol ${device?'TB1':'unidentified'}</span></div><p id="deviceIdentity" class="hint">${device?esc(device.board+' · '+device.sensor+' · firmware '+device.firmware+' · '+device.mode):'Connect a TB1 capture sketch to identify its board, sensor, units, and rate.'}</p><div id="deviceMismatch" class="callout" ${device&&TBAcquisition.mismatch(device,p.axes,p.sampleRate)?'':'hidden'}>${esc(TBAcquisition.mismatch(device,p.axes,p.sampleRate)||'')}</div><div class="actions"><button id="useDevice" ${!device||device.mode!=='capture'||p.records.length||p.recovery?'disabled':''}>Use device settings</button></div><div id="acquisitionStats">${diagnosticsHTML(diagnostics.snapshot())}</div><div id="livePrediction" role="status">${predictionHTML()}</div><p class="hint">Device intervals use the board’s read clock. Browser arrival intervals include USB buffering. Percentiles use the most recent 2,048 intervals; counts cover the connection.</p></section>`;}
function diagnosticsHTML(d){const labels=['<80%','80–95%','95–105%','105–120%','>120%'],total=d.histogram.reduce((a,b)=>a+b,0)||1;return `<div class="stat-row"><div class="stat"><strong>${num(d.measuredHz)}</strong><small>Hz · ${esc(d.clock==='browser'?'browser arrival':d.clock==='unknown'?'waiting':'device clock')}</small></div><div class="stat"><strong>${d.missed}</strong><small>missing sequences</small></div><div class="stat"><strong>${d.invalid+d.duplicates+d.outOfOrder}</strong><small>rejected / repeated</small></div></div><p class="hint">Intervals (ms): min ${num(d.minMs)} · p50 ${num(d.p50Ms)} · p95 ${num(d.p95Ms)} · max ${num(d.maxMs)}<br>Clock/sequence resets: ${d.resets} · uneven device intervals: ${d.uneven}</p><div class="timing-hist" role="img" aria-label="Sampling intervals relative to the configured period: ${labels.map((v,i)=>esc(v)+' '+d.histogram[i]).join('; ')}">${labels.map((v,i)=>`<div><div class="hist-track"><span style="height:${Math.max(d.histogram[i]?3:0,100*d.histogram[i]/total)}%"></span></div><strong>${d.histogram[i]}</strong><small>${esc(v)}</small></div>`).join('')}</div><p class="hint">Interval / configured period · ${d.intervalCount} intervals</p>`;}
function predictionHTML(){if(!lastPrediction)return '';const r=p.runs.find(r=>r.id===device?.model_id),d=lastPrediction,label=d.class_index<0?'Uncertain':r?.labels[d.class_index]||'Class '+d.class_index;return `<div class="callout"><strong>On-board prediction: ${esc(label)}</strong><p class="hint">${num(d.inference_us/1000,3)} ms inference · ${num(d.sample_hz)} Hz ${device?.sensor==='PDM microphone'?'nominal PDM rate':'in last window'}<br>${d.missed} missed ${device?.sensor==='PDM microphone'?'PCM chunks':'samples'} · ${d.dropped} dropped ${device?.sensor==='PDM microphone'?'PCM chunks':'windows'} · ${d.uneven||0} uneven intervals<br>Model: ${esc(device?.model_id||'unknown')}${r?'':' · labels unavailable in this project'}</p><p class="hint">Scores: ${d.scores.map(v=>pct(v)).join(' / ')}</p></div>`;}
function recoveryPanel(){if(!p.recovery||recording)return '';const d=p.recovery,problem=TBAcquisition.quality(d.record,p.sampleRate);return `<section class="panel recovery"><span class="eyebrow">CAPTURE RECOVERY</span><h2>Partial data preserved.</h2><p>${esc(d.reason)}</p><p class="hint">${d.record.rows.length} rows · ${esc(d.record.label)} · session ${esc(d.record.group)}. Excluded from training until kept.</p>${problem?`<p class="hint">Cannot keep for training: ${esc(problem)} Export the raw data for inspection.</p>`:'<p class="hint">Timing checks pass. Keep this shorter recording, or download the raw data.</p>'}<div class="actions"><button id="keepRecovery" ${problem?'disabled':''}>Keep clean partial</button><button id="exportRecovery">Download raw recovery</button><button id="discardRecovery" class="danger">Discard</button></div></section>`;}
function finishBoardAudio(reason){if(!boardAudio)return;clearTimeout(boardAudioTimer);const clip=boardAudio;boardAudio=null;if(typeof reason==='string')clip.problems.push(reason);if(clip.samples.length<512){render();notify('Clip was too short; try again.',true);return;}prepareAudio({samples:clip.samples,origin:'pdm-'+clip.started,source:'Arduino PDM',sourceRate:16000,channels:1,processing:'PCM16 / 32768; no resampling.',problems:clip.problems},'Board microphone');}
function handleSerial(type,data){
 if(type==='audio'&&boardAudio){const c=boardAudio;if(c.lastSeq!==null && ((data.seq-c.lastSeq)>>>0)!==1)c.problems.push('PCM sequence gap');c.lastSeq=data.seq;c.samples.push(...data.samples.slice(0,320000-c.samples.length));if($('#boardAudioStatus'))$('#boardAudioStatus').textContent=(c.samples.length/16000).toFixed(2)+' s · '+c.problems.length+' gaps';if(c.samples.length>=320000)finishBoardAudio();}
 if(['error','interrupted','disconnected'].includes(type)&&boardAudio)finishBoardAudio(String(data||'Connection interrupted'));

 if(type==='connected'){device=null;lastPrediction=null;diagnostics=new TinyDiagnostics(p.sampleRate);validCount=0;badRows=0;latest=[];serialMessage='Identifying device';}
 if(type==='state'){serialMessage=data.state+(data.detail?' · '+data.detail:'');if($('#connectionBadge'))$('#connectionBadge').textContent=data.state;}
 if(type==='device'){if(recording&&device&&JSON.stringify(device)!==JSON.stringify(data))interruptCapture('Device identity changed.');device=data;if(tab==='capture'&&!recording)render();}
 if(type==='invalid'){badRows++;diagnostics.reject();if(recording){recording.problem(data);interruptCapture(data);}}
 if(type==='error'){serialMessage=data;notify(data,true);if(recording)interruptCapture(data);}
 if(type==='interrupted'&&recording)interruptCapture(data);
 if(type==='prediction'){lastPrediction=data;if($('#livePrediction'))$('#livePrediction').innerHTML=predictionHTML();}
 if(type==='disconnected'){serialMessage='Disconnected · retry the selected port or choose a new port';if(recording)interruptCapture('USB connection was interrupted.');if(tab==='capture')render();}
 if($('#serialStatus'))$('#serialStatus').textContent=serialMessage;
}
function handleRow(frame){const mismatch=TBAcquisition.mismatch(device,p.axes,p.sampleRate);if(mismatch||!TBAcquisition.frameMatches(frame,p.axes)){badRows++;diagnostics.reject();serialMessage=mismatch||'Header mismatch — check project channels';if(recording){recording.problem(serialMessage);interruptCapture(serialMessage);}updateSignal();return;}
 const received=performance.now(),result=diagnostics.add(frame,received);if(!result.accept){badRows++;if(recording){recording.problem(result.fault);interruptCapture(result.fault);}updateSignal();return;}
 validCount++;latest.push(frame.values);if(latest.length>256)latest.shift();serialMessage=device?'Receiving TB1 sensor data':'Legacy CSV · device identity and sequence may be unavailable';
 if(recording){const fault=recording.add(frame,received);if(fault)interruptCapture(fault);else if(recording.record.rows.length>=20000)finishRecording();}
 updateSignal();
}
let lastPaint=0,lastDiagnosticsPaint=0;
function updateSignal(){if(tab!=='capture')return;if($('#signalStats'))$('#signalStats').textContent=validCount+' valid rows · '+badRows+' rejected';if($('#serialStatus'))$('#serialStatus').textContent=serialMessage;if($('#signalEmpty'))$('#signalEmpty').hidden=latest.length>0;if(performance.now()-lastPaint>70){lastPaint=performance.now();drawSignal('signalCanvas',latest);}if(performance.now()-lastDiagnosticsPaint>500){lastDiagnosticsPaint=performance.now();if($('#acquisitionStats'))$('#acquisitionStats').innerHTML=diagnosticsHTML(diagnostics.snapshot());}}
function startRecording(){if(training)throw new Error('Finish training before recording.');if(p.recovery)throw new Error('Keep, export, or discard the recovery capture first.');if(!serial.running||serial.state!=='streaming'||!validCount)throw new Error('Connect and wait for a healthy sensor stream.');const mismatch=TBAcquisition.mismatch(device,p.axes,p.sampleRate);if(mismatch)throw new Error(mismatch);const label=$('#captureLabel').value.trim(),group=$('#captureGroup').value.trim(),duration=Number($('#duration').value),split=$('#captureSplit').value;if(!label||!group||!Number.isFinite(duration)||duration<1||duration>30)throw new Error('Enter a label, session ID, and duration from 1 to 30 seconds.');if(p.records.some(r=>r.group===group&&r.split!==split))throw new Error('This session belongs to another partition. Use that partition or a new independent session.');
 recording=new TBAcquisition.Capture({id:uid(),name:label+' '+new Date().toLocaleTimeString(),label,group,split,target:TB.task(p)==='regression'?Number($('#captureTarget').value):undefined,source:'USB serial · 115200 baud'},p.axes,p.sampleRate,device);const started=performance.now();captureCheckpoint=0;$('#recordBtn').textContent='Stop & keep recording';recordTimer=setInterval(()=>{if(!recording)return;const elapsed=(performance.now()-started)/1000;if($('#recordStatus'))$('#recordStatus').textContent=`Recording ${elapsed.toFixed(1)} / ${duration} s · ${recording.record.rows.length} rows`;if(elapsed>=duration)finishRecording();else if(performance.now()-captureCheckpoint>1000){captureCheckpoint=performance.now();p.recovery=recording.draft();requestSave();}},100);
}
function interruptCapture(reason){if(!recording)return;clearInterval(recordTimer);p.recovery=recording.draft(String(reason).slice(0,240));recording=null;requestSave();if(tab==='capture')render();notify('Capture interrupted. Partial rows were preserved for review.',true);}
function finishRecording(){if(!recording)return;clearInterval(recordTimer);try{const r=recording.finish();addRecord(r);recording=null;p.recovery=null;requestSave();notify(`Captured ${r.rows.length} rows as “${r.label}”.`);if(tab==='capture')render();}catch(e){interruptCapture(e.message);}}
function canvasContext(id){const c=$('#'+id);if(!c)return null;const rect=c.getBoundingClientRect();if(!rect.width||!rect.height)return null;const ratio=Math.min(devicePixelRatio||1,2);c.width=rect.width*ratio;c.height=rect.height*ratio;const ctx=c.getContext('2d');ctx.scale(ratio,ratio);return{ctx,w:rect.width,h:rect.height,css:getComputedStyle(document.documentElement)};}
function drawSignal(id,rows){const v=canvasContext(id);if(!v||!rows.length)return;const{ctx,w,h,css}=v,flat=rows.flat(),min=Math.min(...flat),max=Math.max(...flat),span=max-min||1,pad=22;ctx.font='10px monospace';ctx.fillStyle=css.getPropertyValue('--muted');ctx.fillText(max.toFixed(2),8,13);ctx.fillText(min.toFixed(2),8,h-7);for(let a=0;a<rows[0].length;a++){ctx.strokeStyle=css.getPropertyValue('--chart'+(a%3+1));ctx.lineWidth=1.8;ctx.setLineDash(a>=3?[5,3]:[]);ctx.beginPath();rows.forEach((r,i)=>{const x=pad+i/(Math.max(rows.length-1,1))*(w-pad*2),y=h-pad-(r[a]-min)/span*(h-pad*2);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();}}
function drawLoss(history){const v=canvasContext('lossCanvas');if(!v||!history?.length)return;const{ctx,w,h,css}=v,max=Math.max(.05,...history.flatMap(x=>[x.trainLoss,x.valLoss])),pad=22;for(const [i,key]of ['trainLoss','valLoss'].entries()){ctx.beginPath();ctx.strokeStyle=css.getPropertyValue('--chart'+(i+1));ctx.lineWidth=2;history.forEach((p,n)=>{const x=pad+n/Math.max(1,history.length-1)*(w-2*pad),y=h-pad-p[key]/max*(h-2*pad);n?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();}ctx.fillStyle=css.getPropertyValue('--muted');ctx.font='10px monospace';ctx.fillText(max.toFixed(2),4,12);ctx.fillText('0',5,h-15);ctx.fillText('epoch 1',22,h-5);ctx.fillText(String(history.length),w-35,h-5);}
function paintReplay(){const run=activeRun(),r=p.records.find(x=>x.id===replayId);if(!run||!r||!$('#predictionScores'))return;const rows=r.rows.slice(replayOffset,replayOffset+run.config.window);drawSignal('replayCanvas',rows);try{const scores=TB.predict(rows,run);if(TB.task(run)!=='classification'){$('#predictionScores').innerHTML=TB.task(run)==='regression'?`<div class="prediction">${num(scores[0],4)} ${esc(run.target.unit)}</div><p>Reference target: ${num(r.target,4)}</p>`:`<div class="prediction">${scores[0]>run.model.threshold?'Anomaly':'Normal'}</div><p>Score ${num(scores[0],4)} · threshold ${num(run.model.threshold,4)}</p>`;return;}const best=scores.indexOf(Math.max(...scores));$('#predictionScores').innerHTML=`<div class="prediction">${scores[best]<p.threshold?'Uncertain':esc(run.labels[best])}</div><small>Recorded label: ${esc(r.label)}</small>${scores.map((s,i)=>`<div class="score"><div class="score-label"><span>${esc(run.labels[i])}</span><span>${pct(s)}</span></div><div class="score-track"><span style="width:${Math.max(0,Math.min(100,s*100))}%"></span></div></div>`).join('')}`;}catch(e){$('#predictionScores').textContent=e.message;}}
function paint(){if(tab==='capture'){drawSignal('signalCanvas',latest);paintAudio();}if(tab==='dataset'){const r=p.records.find(r=>r.id===selected);if(r){const step=Math.max(1,Math.ceil(r.rows.length/800));drawSignal('recordCanvas',r.rows.filter((_,i)=>i%step===0));}}if(tab==='train')drawLoss(activeRun()?.history);if(tab==='test')paintReplay();}
$('#workflow').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)go(b.dataset.tab);});
bind('theme','change',e=>{document.documentElement.dataset.theme=e.target.value;localStorage.setItem('tinybench-theme',e.target.value);paint();});bind('helpBtn','click',()=>$('#guideDialog').showModal());bind('closeGuide','click',()=>$('#guideDialog').close());bind('guideDemo','click',async()=>{$('#guideDialog').close();await loadDemo();});bind('projectBtn','click',openSettings);bind('saveProjectBtn','click',applySettings);bind('newBtn','click',async()=>{if(await replaceProject(TB.fresh()))go('capture');});bind('backupBtn','click',backup);bind('importBtn','click',()=>$('#projectFile').click());bind('projectFile','change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>128*1024*1024)throw new Error('Project exceeds the 128 MB import limit.');const next=validateLoaded(JSON.parse(await f.text()));if(await replaceProject(next)){go(next.records.length?'dataset':'capture');notify('Project restored, including raw data and trained runs.');}});bind('confirmCSV','click',importCSV);
window.addEventListener('resize',()=>requestAnimationFrame(paint));window.addEventListener('beforeunload',e=>{if(training||recording||microphone.active||boardAudio||$('#saveState').textContent!=='● Saved locally'){e.preventDefault();e.returnValue='';}});
let localToken='',localHealth=null,localJob=null,localPoll=null;
function localWorkerView(){const run=activeRun(),busy=localJob&&['running','queued'].includes(localJob.status);return `<details class="panel" style="margin-top:20px" ${localHealth||localJob?'open':''}><summary>Optional local worker · training and build tools</summary><p class="hint">Start <code>node service/server.cjs</code>, then open the address it prints. These actions send this project's recordings to that same server. The token stays in this tab's memory.</p><div class="controls"><label>Worker token<input id="localToken" type="password" autocomplete="off" placeholder="Paste token printed by your worker" value="${esc(localToken)}"></label><label>Compile target<select id="localBoard"><option value="sense">Nano 33 BLE Sense · Mbed Nano</option><option value="iot">Nano 33 IoT · SAMD</option></select></label><label>TFLite format<select id="localQuant"><option value="int8">Full integer int8</option><option value="float32">Float32</option></select></label></div><div class="actions"><button id="localConnect">${localHealth?'Reconnect worker':'Connect worker'}</button><button id="localTrain" ${!localHealth?.capabilities.train||busy||training?'disabled':''}>Send dataset & train</button><button id="localTFLite" ${!run||stale(run)||TB.task(run)==='anomaly'||!localHealth?.capabilities.tflite||busy?'disabled':''}>Send dataset & convert TFLite</button><button id="localCompile" ${!run||stale(run)||!localHealth?.capabilities.compile||busy?'disabled':''}>Compile native Arduino library</button>${busy?'<button id="localCancel">Cancel worker job</button>':''}${localJob?.status==='done'?'<button id="localDownload">Download worker artifact</button>':''}</div><p id="localStatus" class="hint" role="status">${esc(localJob?localJob.kind+' · '+localJob.status+' · '+(localJob.progress?.stage||'')+(localJob.cached?' · cached':''):localHealth?'Connected. One job at a time; 10-minute limit.':'Worker not connected. Browser training and Arduino source export remain available.')}</p>${localJob?.error?'<pre class="hint" style="white-space:pre-wrap">'+esc(localJob.error)+'</pre>':''}<p class="hint">Arduino builds compile the StaticBuffer example and return binaries, compiler size output, tool versions, and checksums. They do not upload firmware. TFLite includes an int8/float model and a TensorFlow Lite Micro integration template; that template requires a separately installed runtime and remains unqualified on hardware.</p></details>`;}
async function localRequest(url,options={}){const response=await fetch(url,{...options,headers:{'Authorization':'Bearer '+localToken,...(options.body?{'Content-Type':'application/json'}:{})},cache:'no-store'});if(!response.ok){let error;try{error=(await response.json()).error;}catch{}throw new Error(error||'Local worker unavailable. Start it and open its printed localhost address.');}return response;}
async function connectLocal(){localToken=$('#localToken').value.trim();localHealth=await(await localRequest('./api/health')).json();if(p.localJobId){try{localJob=await(await localRequest('./api/jobs/'+p.localJobId)).json();scheduleLocalPoll();}catch(e){localJob=null;delete p.localJobId;requestSave();notify('Connected. The previous worker job is no longer available; start a new job.',true);}}render();}
async function startLocal(kind){guardTraining();if(localJob&&['running','queued'].includes(localJob.status))throw new Error('Finish or cancel the current worker job first.');const run=activeRun();if(kind!=='train'&&(!run||stale(run)))throw new Error('Train a current model first.');const project=TB.clone(p);project.runs=[];project.revisions=[];delete project.audioDraft;delete project.recovery;localJob=await(await localRequest('./api/jobs',{method:'POST',body:JSON.stringify({kind,project,run:kind==='train'?undefined:run,board:$('#localBoard').value,quantization:$('#localQuant').value})})).json();p.localJobId=localJob.id;requestSave();render();scheduleLocalPoll();}
function scheduleLocalPoll(){clearTimeout(localPoll);if(!localJob)return;if(['running','queued'].includes(localJob.status))localPoll=setTimeout(safe(pollLocal),1000);else if(localJob.status==='done'&&localJob.kind==='train')safe(acceptLocalRun)();}
async function pollLocal(){try{localJob=await(await localRequest('./api/jobs/'+localJob.id)).json();if($('#localStatus'))$('#localStatus').textContent=localJob.kind+' · '+localJob.status+' · '+(localJob.progress?.stage||'');if(!['queued','running'].includes(localJob.status))render();scheduleLocalPoll();}catch(e){notify('Worker connection interrupted. Reconnect to recover job status. '+e.message,true);}}
async function acceptLocalRun(){const run=TB.validateRun(await(await localRequest('./api/jobs/'+localJob.id+'/run')).json());if(run.signature!==TB.signature(p)){notify('Worker model belongs to an earlier dataset. Download its artifact to preserve it.',true);return;}if(p.runs.some(r=>r.id===run.id))return;while(p.runs.length>=8)p.runs.splice(p.runs.findIndex(r=>r.id!==p.baseline),1);p.runs.push(run);p.activeRun=run.id;requestSave();render();notify('Worker training complete. Model added to this notebook.');}
function bindLocal(){bind('localConnect','click',connectLocal);bind('localTrain','click',()=>startLocal('train'));bind('localTFLite','click',()=>startLocal('tflite'));bind('localCompile','click',()=>startLocal('compile'));bind('localCancel','click',async()=>{localJob=await(await localRequest('./api/jobs/'+localJob.id,{method:'DELETE'})).json();clearTimeout(localPoll);render();});bind('localDownload','click',async()=>download(await(await localRequest('./api/jobs/'+localJob.id+'/artifact')).blob(),'TinyBench-'+localJob.kind+'.zip'));}

init().catch(e=>notify('Startup failed: '+e.message,true));
